func testCstpiscofinToManyAddOpDocumentoVendaItems(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Cstpiscofin
	var b, c, d, e DocumentoVendaItem

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, cstpiscofinDBTypes, false, strmangle.SetComplement(cstpiscofinPrimaryKeyColumns, cstpiscofinColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*DocumentoVendaItem{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, documentoVendaItemDBTypes, false, strmangle.SetComplement(documentoVendaItemPrimaryKeyColumns, documentoVendaItemColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = c.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	foreignersSplitByInsertion := [][]*DocumentoVendaItem{
		{&b, &c},
		{&d, &e},
	}

	for i, x := range foreignersSplitByInsertion {
		err = a.AddDocumentoVendaItems(ctx, tx, i != 0, x...)
		if err != nil {
			t.Fatal(err)
		}

		first := x[0]
		second := x[1]

		if a.CstpiscofinsID != first.CstpiscofinsID {
			t.Error("foreign key was wrong value", a.CstpiscofinsID, first.CstpiscofinsID)
		}
		if a.CstpiscofinsID != second.CstpiscofinsID {
			t.Error("foreign key was wrong value", a.CstpiscofinsID, second.CstpiscofinsID)
		}

		if first.R.Cstpiscofin != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}
		if second.R.Cstpiscofin != &a {
			t.Error("relationship was not added properly to the foreign slice")
		}

		if a.R.DocumentoVendaItems[i*2] != first {
			t.Error("relationship struct slice not set to correct value")
		}
		if a.R.DocumentoVendaItems[i*2+1] != second {
			t.Error("relationship struct slice not set to correct value")
		}

		count, err := a.DocumentoVendaItems().Count(ctx, tx)
		if err != nil {
			t.Fatal(err)
		}
		if want := int64((i + 1) * 2); count != want {
			t.Error("want", want, "got", count)
		}
	}
}
