func testCstpiscofinToManyRemoveOpProdutoEntidades(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Cstpiscofin
	var b, c, d, e ProdutoEntidade

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, cstpiscofinDBTypes, false, strmangle.SetComplement(cstpiscofinPrimaryKeyColumns, cstpiscofinColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	foreigners := []*ProdutoEntidade{&b, &c, &d, &e}
	for _, x := range foreigners {
		if err = randomize.Struct(seed, x, produtoEntidadeDBTypes, false, strmangle.SetComplement(produtoEntidadePrimaryKeyColumns, produtoEntidadeColumnsWithoutDefault)...); err != nil {
			t.Fatal(err)
		}
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	err = a.AddProdutoEntidades(ctx, tx, true, foreigners...)
	if err != nil {
		t.Fatal(err)
	}

	count, err := a.ProdutoEntidades().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 4 {
		t.Error("count was wrong:", count)
	}

	err = a.RemoveProdutoEntidades(ctx, tx, foreigners[:2]...)
	if err != nil {
		t.Fatal(err)
	}

	count, err = a.ProdutoEntidades().Count(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}
	if count != 2 {
		t.Error("count was wrong:", count)
	}

	if !queries.IsValuerNil(b.CstpiscofinsID) {
		t.Error("want b's foreign key value to be nil")
	}
	if !queries.IsValuerNil(c.CstpiscofinsID) {
		t.Error("want c's foreign key value to be nil")
	}

	if b.R.Cstpiscofin != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if c.R.Cstpiscofin != nil {
		t.Error("relationship was not removed properly from the foreign struct")
	}
	if d.R.Cstpiscofin != &a {
		t.Error("relationship to a should have been preserved")
	}
	if e.R.Cstpiscofin != &a {
		t.Error("relationship to a should have been preserved")
	}

	if len(a.R.ProdutoEntidades) != 2 {
		t.Error("should have preserved two relationships")
	}

	// Removal doesn't do a stable deletion for performance so we have to flip the order
	if a.R.ProdutoEntidades[1] != &d {
		t.Error("relationship to d should have been preserved")
	}
	if a.R.ProdutoEntidades[0] != &e {
		t.Error("relationship to e should have been preserved")
	}
}

